-- Read-only score preparation; no source lease, native issuer or write capability.
-- Original17/300/DA functions remain unchanged.
create schema private_fcf_g1_scores;
revoke all on schema private_fcf_g1_scores from public,anon,authenticated,service_role;
create function private_fcf_g1_scores.rules_sha()returns text language sql stable security definer set search_path=pg_catalog,pg_temp as $$
 select encode(sha256(convert_to(jsonb_build_object('appearancePoints',pg_get_viewdef('public.appearance_points'::regclass,true),'routines',(select jsonb_agg(jsonb_build_array(n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),p.proowner,p.proacl,p.proconfig,p.prosecdef,encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'))order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.prokind='f'and(n.nspname in('public','scout')or n.nspname like 'private\_%'escape '\')))::text,'UTF8')),'hex')
$$;
create function private_fcf_g1_scores.score_before()returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 with scope as(select array(select id from rounds where competition_id=783)rids,array(select id from players where competition_id=783)pids),actual as(select coalesce(jsonb_agg(to_jsonb(ps)order by to_jsonb(ps)::text collate "C"),'[]')::text t from player_scores ps cross join scope s where ps.round_id=any(s.rids)or ps.player_id=any(s.pids)),expected as(select coalesce(jsonb_agg(to_jsonb(x)order by x.round_id,x.player_id),'[]')::text t from(select ap.round_id,ap.player_id,sum(ap.points)points from appearance_points ap cross join scope s where ap.round_id=any(s.rids)or ap.player_id=any(s.pids)group by ap.round_id,ap.player_id)x)
 select jsonb_build_object('beforeImageText',a.t,'beforeSha256',encode(sha256(convert_to(a.t,'UTF8')),'hex'),'expectedBeforeText',e.t,'expectedBeforeSha256',encode(sha256(convert_to(e.t,'UTF8')),'hex'),'rulesSha256',private_fcf_g1_scores.rules_sha())from actual a cross join expected e
$$;
create function private_fcf_g1_scores.assert_scores(b jsonb,require_baseline boolean)returns void language plpgsql stable security definer set search_path=public,pg_temp as $$
declare actual jsonb:=private_fcf_g1_scores.score_before();begin
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(b,array['kind','count','beforeImageText','beforeSha256','expectedBeforeText','expectedBeforeSha256','rulesSha256','roundCounts','strictZeroAffectedUsersObserved'])and b->'strictZeroAffectedUsersObserved'='false'::jsonb and b->>'kind'='fcf-g1-derived-score-before'and b->>'rulesSha256'=actual->>'rulesSha256','exact unchanged SQL scoring rules');
 perform private_fcf_six_target_release.require(octet_length(b->>'beforeImageText')between 2 and 8388608 and octet_length(b->>'expectedBeforeText')between 2 and 8388608 and b->>'beforeSha256'=encode(sha256(convert_to(b->>'beforeImageText','UTF8')),'hex')and b->>'expectedBeforeSha256'=encode(sha256(convert_to(b->>'expectedBeforeText','UTF8')),'hex')and jsonb_typeof((b->>'beforeImageText')::jsonb)='array'and jsonb_typeof((b->>'expectedBeforeText')::jsonb)='array'and b->>'count'=jsonb_array_length((b->>'beforeImageText')::jsonb)::text and b->>'expectedBeforeText'=actual->>'expectedBeforeText'and b->>'expectedBeforeSha256'=actual->>'expectedBeforeSha256','bounded exact beforeimage hashes/count and canonical semantic beforeimage');
 perform private_fcf_six_target_release.require(not exists(select 1 from jsonb_array_elements((b->>'beforeImageText')::jsonb)x where not private_fcf_future_import.keys(x,array['round_id','player_id','points','computed_at'])or not exists(select 1 from rounds r where r.id=(x->>'round_id')::bigint and r.competition_id=783)or not exists(select 1 from players p where p.id=(x->>'player_id')::bigint and p.competition_id=783))and not exists(select 1 from jsonb_array_elements((b->>'beforeImageText')::jsonb)x group by x->'round_id',x->'player_id'having count(*)<>1),'closed unique actual target score row identities');
 perform private_fcf_six_target_release.require(b->'roundCounts'=(select coalesce(jsonb_agg(jsonb_build_object('roundId',r.id,'userRows',(select count(*)from player_scores ps where ps.round_id=r.id))order by r.id),'[]')from rounds r where r.competition_id=783),'all strict score round counters preserved');
 perform private_fcf_six_target_release.require(not exists(with expected as(select x->'round_id'round_id,x->'player_id'player_id,x->'points'points from jsonb_array_elements((actual->>'expectedBeforeText')::jsonb)x),stored as(select x->'round_id'round_id,x->'player_id'player_id,x->'points'points from jsonb_array_elements((actual->>'beforeImageText')::jsonb)x)(select *from expected except all select *from stored)union all(select *from stored except all select *from expected)),'every actual score must be rederived from actual canonical appearances and unchanged SQL rules');
 perform private_fcf_six_target_release.require(not exists(with expected as(select x->'round_id'round_id,x->'player_id'player_id,x->'points'points from jsonb_array_elements((actual->>'expectedBeforeText')::jsonb)x),submitted as(select x->'round_id'round_id,x->'player_id'player_id,x->'points'points from jsonb_array_elements((b->>'beforeImageText')::jsonb)x)(select *from expected except all select *from submitted)union all(select *from submitted except all select *from expected)),'submitted full rows must reproduce every independently derived score');
 if require_baseline then
  perform private_fcf_six_target_release.require(b->'count'='924'::jsonb and b->>'beforeSha256'='f28f4dec5bff6e6ba7ea933d1d83c594f69ed2721c84b48567e30bd5b1243ba1'and jsonb_array_length((b->>'beforeImageText')::jsonb)=924 and b->>'beforeImageText'=actual->>'beforeImageText'and b->>'beforeSha256'=actual->>'beforeSha256'and b->>'expectedBeforeText'=actual->>'expectedBeforeText'and b->>'expectedBeforeSha256'=actual->>'expectedBeforeSha256','exact original924 score rows and full SQL beforeimages required');
 end if;
end$$;
create function private_fcf_g1_scores.assert_supplement_scores(b jsonb)returns void language plpgsql stable security definer set search_path=public,pg_temp as $$declare actual jsonb:=private_fcf_g1_scores.score_before();begin
 perform private_fcf_g1_scores.assert_scores(b,false);
 perform private_fcf_six_target_release.require(b->'count'='924'::jsonb and b->>'beforeSha256'='f28f4dec5bff6e6ba7ea933d1d83c594f69ed2721c84b48567e30bd5b1243ba1','supplement requires the original exact924 authenticated score beforeimage');
 perform private_fcf_six_target_release.require(b->>'expectedBeforeText'=actual->>'expectedBeforeText','placeholder transitions preserve the entire independently rederived924 semantic score set');
 perform private_fcf_six_target_release.require(not exists(select 1 from jsonb_array_elements((actual->>'beforeImageText')::jsonb)a full join jsonb_array_elements((b->>'beforeImageText')::jsonb)z on a->'round_id'=z->'round_id'and a->'player_id'=z->'player_id'where a is null or z is null or a-'computed_at'<>z-'computed_at'or((a->>'computed_at')::timestamptz is distinct from(z->>'computed_at')::timestamptz and(a->>'computed_at')::timestamptz is distinct from transaction_timestamp())),'only ordinary recompute transaction timestamps may change during empty supplement header installation');
end$$;
create function private_fcf_g1_scores.guard_before(v jsonb,p jsonb)returns void language plpgsql stable security definer set search_path=public,pg_temp as $$declare b jsonb:=v->'derivedScoresBefore';d jsonb:=p#>'{native,dependencies}';x jsonb;live jsonb;begin
 live:=private_fcf_g1_readonly.capture('es-ct-segona-g1',array(select jsonb_array_elements_text(p#>'{databaseInventory,identityPrivacy,checkedKeys}')));
 perform private_fcf_six_target_release.require(p->>'dependencySnapshotText'=live->>'dependencySnapshotText'and p->>'dependencySnapshotSha256'=live->>'dependencySnapshotSha256','complete live locked dependency projection must match the full submitted beforeimage');
 perform private_fcf_six_target_release.require(v->>'nativeSnapshotText'=p->>'dependencySnapshotText'and v->>'nativeSnapshotSha256'=p->>'dependencySnapshotSha256'and encode(sha256(convert_to(v->>'nativeSnapshotText','UTF8')),'hex')=p->>'dependencySnapshotSha256'and d->>'complete'='true'and d->>'competitionUserRows'='0','complete locked exact native/dependency beforeimage and zero human dependencies');
 perform private_fcf_g1_scores.assert_scores(b,true);
 perform private_fcf_six_target_release.require(jsonb_array_length(d->'rounds')=30 and jsonb_array_length(d->'matches')=240 and(select count(distinct x->>'roundId')from jsonb_array_elements(d->'rounds')x)=30 and(select count(distinct x->>'matchId')from jsonb_array_elements(d->'matches')x)=240 and not exists(select 1 from rounds r where r.competition_id=783 and not exists(select 1 from jsonb_array_elements(d->'rounds')x where(x->>'roundId')::bigint=r.id)),'complete unique actual round dependency coverage');
 for x in select value from jsonb_array_elements(d->'rounds')loop
  perform private_fcf_six_target_release.require(x->>'lineupRows'='0'and x->>'rosterRows'='0'and x->>'transferRows'='0'and x->>'chipRows'='0'and(x->>'userRows')::bigint=(select count(*)from player_scores where round_id=(x->>'roundId')::bigint),'nonzero strict round counter must be precisely the independently rederived score set; never subtract unknown rows');
 end loop;
 perform private_fcf_six_target_release.require(not exists(select 1 from jsonb_array_elements(d->'matches')x where x->>'userRows'<>'0'),'zero human match dependencies');
end$$;
create function public.fcf_g1_derived_scores_prepare(p_privacy_keys text[])returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$begin
 perform private_fcf_six_target_release.require(current_setting('transaction_read_only')='on','explicit readonly transaction required');
 return jsonb_build_object('projection',private_fcf_g1_readonly.capture('es-ct-segona-g1',p_privacy_keys),'derivedScoresBefore',private_fcf_g1_scores.score_before());
end$$;
revoke all on all functions in schema private_fcf_g1_scores from public,anon,authenticated,service_role;
revoke all on function public.fcf_g1_derived_scores_prepare(text[])from public,anon,authenticated;
grant execute on function public.fcf_g1_derived_scores_prepare(text[])to service_role;
